package dev.workshopvideo;
import android.content.*;import java.io.*;import java.nio.file.*;import java.util.*;import java.util.concurrent.*;
public class DownloadServiceChecks {
 static int checks;static void check(boolean ok,String title){if(!ok)throw new AssertionError(title);checks++;}interface Condition{boolean ready();}static void until(Condition c,String title)throws Exception{long end=System.nanoTime()+TimeUnit.SECONDS.toNanos(3);while(!c.ready()&&System.nanoTime()<end)new CountDownLatch(1).await(5,TimeUnit.MILLISECONDS);check(c.ready(),title);}static Intent start(String id){return new Intent().putExtra("id",id);}static Intent stop(String id,boolean cancel){return start(id).setAction(cancel?VideoDownloadService.CANCEL:VideoDownloadService.PAUSE);}
 public static void main(String[] args)throws Exception{
  Path root=Files.createTempDirectory("download-service-");VideoApp app=new VideoApp(root);Context.application=app;VideoDownloadService service=new VideoDownloadService();service.onCreate();String active="1".repeat(32),paused="2".repeat(32),cancelled="3".repeat(32),saved="4".repeat(32);
  try{
   app.add(active);service.onStartCommand(start(active),0,1);check(app.entered.await(2,TimeUnit.SECONDS),"production service enters active session preparation");
   app.add(paused);service.onStartCommand(start(paused),0,2);service.onStartCommand(stop(paused,false),0,3);until(()->app.job(paused).optString("state").equals("paused")&&!app.enqueued.contains(paused),"queued pause settles promptly in real service");check(app.partial(paused).isFile()&&app.transfer(paused).isDirectory(),"pause preserves resumable files");check(app.sessions.get()==1,"paused queued transfer never starts session/network work");
   app.add(cancelled);service.onStartCommand(start(cancelled),0,4);service.onStartCommand(stop(cancelled,true),0,5);until(()->!app.has(cancelled),"queued cancel removes real task record");check(!app.partial(cancelled).exists()&&!app.transfer(cancelled).exists(),"queued cancel cleans partial and per-file cache");check(app.enqueued.contains(active)&&app.interrupted.get()==0,"stopping queued transfer leaves another active transfer running");
   service.onStartCommand(stop(active,false),0,6);until(()->app.job(active).optString("state").equals("paused")&&!app.enqueued.contains(active),"active pause interrupts preparation and settles");check(app.interrupted.get()==1&&app.partial(active).isFile(),"active pause preserves bytes after interruption");
   app.change(active,"cancelRequested",false);app.change(active,"discardRequested",false);app.entered=new CountDownLatch(1);service.onStartCommand(start(active),0,7);check(app.entered.await(2,TimeUnit.SECONDS),"paused production task can resume without stale stop state");service.onStartCommand(stop(active,true),0,8);until(()->!app.has(active),"active cancel waits for worker exit then removes record");check(!app.partial(active).exists()&&!app.transfer(active).exists(),"active cancel removes all unfinished local resources");
   app.add(saved);app.change(saved,"state","saved");Files.write(app.video(saved).toPath(),new byte[]{8});service.onStartCommand(stop(saved,true),0,9);check(app.has(saved)&&app.video(saved).isFile(),"late cancel cannot delete a completed saved video");
   until(()->app.enqueued.isEmpty(),"all stopped jobs leave active task set");check(app.job(paused).optString("state").equals("paused"),"canceling another transfer does not remove paused task");
  }finally{app.gate.countDown();service.onDestroy();app.work.shutdownNow();try(var paths=Files.walk(root)){for(Path p:paths.sorted(Comparator.reverseOrder()).toList())Files.deleteIfExists(p);}}
  System.out.println("PASS: "+checks+" production download-service pause/cancel/cleanup checks with host Android/session fixtures; not phone UI validation");
 }
}
